mapper.select:
SELECT 1 as entry_count
  FROM cdm_own.cmpt_bbs_read_sts
 WHERE bbs_id = #{bbsId}
   AND pst_id = #{pstId}
   AND mbr_id = #{mbrId}

mapper.update:
UPDATE cdm_own.cmpt_bbs_read_sts
   SET last_read_dt = NOW(),
       read_cnt = read_cnt + 1
 WHERE bbs_id = #{bbsId}
   AND pst_id = #{pstId}
   AND mbr_id = #{mbrId}

UPDATE cdm_own.cmpt_bbs_read_sts
   SET view_use_yn = #{viewUseYn} 
 WHERE bbs_id = #{bbsId}
   AND pst_id = #{pstId}
   AND mbr_id = #{mbrId}

UPDATE cdm_own.cmpt_srvc_qstn
   SET rgtr_ans_read_dt = NOW()
      ,mdfr_id = #{mbrId}
      ,mdfcn_dt = NOW()
 WHERE srvc_qstn_id = #{srvcQstnId}
   AND cmpy_id = #{cmpyId}

UPDATE cdm_own.cmpt_srvc_qstn
   SET view_use_yn = #{viewUseYn}
      ,mdfr_id = #{mbrId}
      ,mdfcn_dt = NOW()
 WHERE srvc_qstn_id = #{srvcQstnId}
   AND cmpy_id = #{cmpyId}

UPDATE cdm_own.cmpt_ums_rcvr
SET send_rslt_cd = #{sendRsltCd}
WHERE ums_id = #{umsId}
  and ums_sn = #{umsSn}
  and cmpy_id = #{cmpyId}
  and mbr_id = #{mbrId}
